import{_ as a,b as t,d as o,ah as r}from"./chunks/framework.7NXsYIIo.js";const u=JSON.parse('{"title":"Node.js Foundations at a glance","description":"","frontmatter":{"outline":[2,2]},"headers":[],"relativePath":"node-js/tech-check/foundations-at-a-glance.md","filePath":"node-js/tech-check/foundations-at-a-glance.md"}'),n={name:"node-js/tech-check/foundations-at-a-glance.md"};function s(i,e,c,l,d,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="node-js-foundations-at-a-glance" tabindex="-1">Node.js Foundations at a glance <a class="header-anchor" href="#node-js-foundations-at-a-glance" aria-label="Permalink to “Node.js Foundations at a glance”">​</a></h1><p>One short reminder for each of the <strong>56 questions</strong> in the Foundations explanation pages. Read a topic, recall the idea, then use its link if you need the full answer or diagram. Deeper topics are included too; follow each chapter&#39;s first-pass guidance when deciding what to practise next.</p><h2 id="core-javascript" tabindex="-1">Core JavaScript <a class="header-anchor" href="#core-javascript" aria-label="Permalink to “Core JavaScript”">​</a></h2><ul><li><a href="./core-javascript.html#t26-q01">Object references and copies</a>: <strong>Assignment shares the same object.</strong> Spread creates a new outer object, but nested objects can still be shared.</li><li><a href="./core-javascript.html#t26-q02">Function calls and <code>this</code></a>: <strong>An ordinary function gets <code>this</code> from how it is called; an arrow gets it from its surrounding scope.</strong> Use <code>bind()</code> or a wrapper to preserve a method&#39;s receiver.</li><li><a href="./core-javascript.html#t26-q03">Closures</a>: <strong>A closure keeps access to its surrounding variables.</strong> Functions from one outer call can share state; separate outer calls create separate local state.</li></ul><h2 id="runtime-fundamentals" tabindex="-1">Runtime fundamentals <a class="header-anchor" href="#runtime-fundamentals" aria-label="Permalink to “Runtime fundamentals”">​</a></h2><ul><li><a href="./01-runtime-fundamentals.html#t01-q01">Node and the browser</a>: <strong>V8 executes JavaScript; Node adds host APIs</strong> for files, processes and networking. Node has no page or DOM by default.</li><li><a href="./01-runtime-fundamentals.html#t01-q02">Nonblocking execution</a>: <strong>Other work can progress while I/O waits.</strong> Adding <code>async</code> does not move a calculation to another thread.</li><li><a href="./01-runtime-fundamentals.html#t01-q03">Sync versus async files</a>: <strong>Sync file calls block the current JavaScript thread.</strong> Prefer async calls in request handlers; a small sync startup or CLI read can be reasonable.</li><li><a href="./01-runtime-fundamentals.html#t01-q04">CLI versus service</a>: <strong>A CLI usually finishes one task; a service keeps accepting work.</strong> Both can use built-in modules without installing packages and must close their resources.</li></ul><h2 id="cli-and-process-management" tabindex="-1">CLI and process management <a class="header-anchor" href="#cli-and-process-management" aria-label="Permalink to “CLI and process management”">​</a></h2><ul><li><a href="./02-cli-and-processes.html#t02-q01">Flags and arguments</a>: <strong>Node options usually go before the script; application arguments go after it.</strong> <code>execArgv</code> holds runtime options; <code>argv</code> includes the executable, script and application arguments.</li><li><a href="./02-cli-and-processes.html#t02-q02">Environment configuration</a>: <strong>Environment values are strings: validate and convert them at startup.</strong> Missing may mean default; invalid means failure. <code>Boolean(&#39;false&#39;)</code> is <code>true</code>.</li><li><a href="./02-cli-and-processes.html#t02-q03">REPL</a>: <strong>The interactive prompt remembers previous inputs.</strong> Reproduce important findings in a fresh file or test with explicit setup.</li><li><a href="./02-cli-and-processes.html#t02-q04">Standard streams</a>: <strong>stdin reads input, stdout carries results, stderr carries diagnostics.</strong> A failed CLI also needs a nonzero exit status.</li><li><a href="./02-cli-and-processes.html#t02-q05">Process lifetime</a>: <strong>Active referenced resources can keep Node running; a pending promise alone does not.</strong> <code>exitCode</code> allows natural completion; <code>exit()</code> may interrupt output and cleanup.</li><li><a href="./02-cli-and-processes.html#t02-q06">Process diagnostics</a>: <strong>Working directory differs from module location; elapsed time differs from CPU time.</strong> JavaScript heap use is only part of process memory.</li><li><a href="./02-cli-and-processes.html#t02-q07">Starting programs</a>: <strong><code>spawn</code> streams output; <code>execFile</code> normally buffers it; <code>exec</code> adds a shell.</strong> Prefer direct executable arguments when shell features are unnecessary, and observe failures and closure.</li><li><a href="./02-cli-and-processes.html#t02-q08">Fork and IPC</a>: <strong><code>fork()</code> creates another Node process with a message channel.</strong> Validate replies and observe completion; sending a message does not prove the task finished.</li></ul><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><ul><li><a href="./03-modules.html#t03-q01">Import specifiers</a>: <strong>Built-in, relative-file and package imports use different lookup rules.</strong> A relative import starts from the importing file, not the working directory.</li><li><a href="./03-modules.html#t03-q02">CommonJS and ESM</a>: <strong>CommonJS uses <code>require</code>/<code>module.exports</code>; ESM uses <code>import</code>/<code>export</code>.</strong> <code>.cjs</code> and <code>.mjs</code> make the format explicit; <code>.js</code> depends on package/runtime context.</li><li><a href="./03-modules.html#t03-q03">Scope and cache</a>: <strong>Module-private state can still be shared by callers of the same cached instance.</strong> Separate processes have separate caches and memory.</li><li><a href="./03-modules.html#t03-q04"><code>exports</code> assignment</a>: <strong><code>module.exports</code> is what <code>require()</code> receives.</strong> Changing <code>exports.name</code> can update it; reassigning the local <code>exports</code> variable does not replace it.</li><li><a href="./03-modules.html#t03-q05">Package entry points</a>: <strong><code>exports</code> takes priority over <code>main</code></strong> in supported Node package resolution. Conditions can select different entries; <code>imports</code> defines package-local <code>#</code> shortcuts.</li><li><a href="./03-modules.html#t03-q06">Async module loading</a>: <strong>Dynamic <code>import()</code> returns a promise; top-level <code>await</code> delays module readiness.</strong> A dependency graph containing top-level await cannot finish through synchronous <code>require()</code>.</li><li><a href="./03-modules.html#t03-q07">Loading failures</a>: <strong>Finding a module and successfully running it are different stages.</strong> Check the actual runtime, file format, selected entry, exports and initialization failure.</li><li><a href="./03-modules.html#t03-q08">Cycles and reloading</a>: <strong>Cycles can expose partial CommonJS exports or uninitialized ESM bindings.</strong> Clearing a cache does not close old sockets, pools or timers.</li></ul><h2 id="package-management" tabindex="-1">Package management <a class="header-anchor" href="#package-management" aria-label="Permalink to “Package management”">​</a></h2><ul><li><a href="./04-package-management.html#t04-q01">Manifest and runtime</a>: <strong><code>package.json</code> declares contracts; npm installs dependencies; Node loads code.</strong> <code>&quot;private&quot;: true</code> prevents accidental npm publication, not access to files.</li><li><a href="./04-package-management.html#t04-q02">Install versus clean install</a>: <strong><code>npm install</code> can change the dependency graph; <code>npm ci</code> recreates a compatible lockfile&#39;s graph.</strong> The build stage may need development tools absent from the runtime stage.</li><li><a href="./04-package-management.html#t04-q03">npm configuration</a>: <strong>Flags, environment and configuration files all affect npm.</strong> Inspect the effective nonsecret settings and failure stage before changing them.</li><li><a href="./04-package-management.html#t04-q04">Scripts and hooks</a>: <strong>An npm script does what its configured command says.</strong> <code>--</code> forwards arguments; pre/post hooks can add work, but post hooks are not guaranteed cleanup.</li><li><a href="./04-package-management.html#t04-q05">Versions and ranges</a>: <strong>A range allows versions; a lockfile records a specific resolution.</strong> Caret rules tighten before 1.0, prereleases need care, and <code>ci</code> does not automatically upgrade.</li><li><a href="./04-package-management.html#t04-q06">Registries and packages</a>: <strong>Inspect the tarball consumers actually receive.</strong> Tags can move; integrity checks verify expected bytes, not whether the code is trustworthy.</li><li><a href="./04-package-management.html#t04-q07">Build artifacts</a>: <strong>npm orchestrates tools; the configured tools build the output.</strong> Check the emitted artifact that will run, including missing or stale files.</li><li><a href="./04-package-management.html#t04-q08">Dependency debugging</a>: <strong>Find the failing stage and change one cause at a time.</strong> Deleting the lockfile or forcing upgrades can hide the original problem.</li></ul><h2 id="asynchronous-programming" tabindex="-1">Asynchronous programming <a class="header-anchor" href="#asynchronous-programming" aria-label="Permalink to “Asynchronous programming”">​</a></h2><ul><li><a href="./05-asynchronous-programming.html#t05-q01">Callbacks</a>: <strong>An error-first callback reports <code>(error, result)</code> and a one-result operation should complete once.</strong> Callbacks can run immediately or later; document timing and return after reporting failure.</li><li><a href="./05-asynchronous-programming.html#t05-q02">Promises</a>: <strong>Every <code>.then()</code> creates a new promise.</strong> Return values or promises to keep the chain connected; throws reject it. The executor runs now; handlers run later.</li><li><a href="./05-asynchronous-programming.html#t05-q03"><code>async</code> and <code>await</code></a>: <strong><code>await</code> pauses the async function, not the whole JavaScript thread.</strong> Await owned work inside <code>try</code> and await required cleanup in <code>finally</code>.</li><li><a href="./05-asynchronous-programming.html#t05-q04">Async error ownership</a>: <strong>A surrounding catch does not own every later callback or detached promise.</strong> Handle each failure channel explicitly; <code>emit()</code> does not await async listeners.</li><li><a href="./05-asynchronous-programming.html#t05-q05">Control flow</a>: <strong>Sequence dependent work; overlap independent I/O; limit large collections before starting them.</strong> <code>Promise.all()</code> does not limit concurrency.</li><li><a href="./05-asynchronous-programming.html#t05-q06">Promise combinators</a>: <strong><code>all</code>: every success; <code>allSettled</code>: every outcome; <code>any</code>: first success; <code>race</code>: first outcome.</strong> None automatically cancels the other operations.</li><li><a href="./05-asynchronous-programming.html#t05-q07">Timeout and cancellation</a>: <strong>A timeout ends a wait; cancellation asks cooperative work to stop.</strong> Pass supported abort signals, clean up timers/listeners and remember that completed effects remain.</li><li><a href="./05-asynchronous-programming.html#t05-q08">Async iteration</a>: <strong><code>for await</code> requests the next value after the current body finishes.</strong> Early break calls an available iterator <code>return()</code>; the producer still needs a sound cleanup contract.</li><li><a href="./05-asynchronous-programming.html#t05-q09">Synchronous generators</a>: <strong><code>next()</code> starts or resumes the generator; <code>yield</code> pauses it; <code>done</code> marks completion.</strong> Yielding does not itself give event-loop callbacks a turn.</li></ul><h2 id="core-apis" tabindex="-1">Core APIs <a class="header-anchor" href="#core-apis" aria-label="Permalink to “Core APIs”">​</a></h2><ul><li><a href="./07-core-apis.html#t07-q01">Console</a>: <strong><code>log</code>/<code>info</code> use stdout; <code>warn</code>/<code>error</code> use stderr.</strong> <code>console.assert()</code> reports rather than throws; logging can affect timing and expose secrets.</li><li><a href="./07-core-apis.html#t07-q02">File completion</a>: <strong>Callbacks and promises report the same asynchronous work differently.</strong> Await writes before further writes to the same target; close handles you open. Without a text encoding, <code>readFile</code> returns a Buffer.</li><li><a href="./07-core-apis.html#t07-q03">Paths</a>: <strong>Path helpers transform strings, not filesystem permissions.</strong> A normalized path can still be missing, unauthorized or redirected by a symbolic link.</li><li><a href="./07-core-apis.html#t07-q04">OS information</a>: <strong>Host facts are hints, not a resource allowance.</strong> System memory differs from the JavaScript heap limit; choose concurrency using deployment limits and measurements.</li><li><a href="./07-core-apis.html#t07-q05">Buffers</a>: <strong>Text length differs from encoded byte length.</strong> <code>Buffer.from(buffer)</code> copies; Buffer <code>subarray()</code> and <code>slice()</code> share storage, so edits and memory retention can be shared.</li><li><a href="./07-core-apis.html#t07-q06">Chunked text</a>: <strong>A character can span byte chunks; <code>StringDecoder</code> keeps incomplete bytes until more arrive.</strong> Flush with <code>end()</code>; tolerant decoding is not strict input validation.</li><li><a href="./07-core-apis.html#t07-q07">Timers</a>: <strong>Delay means earliest eligibility, not exact execution time.</strong> <code>unref()</code> does not cancel; <code>setInterval()</code> does not await async work and can overlap runs.</li><li><a href="./07-core-apis.html#t07-q08">URLs</a>: <strong>Parse with <code>URL</code> and handle query values with <code>URLSearchParams</code>.</strong> Absolute inputs can replace the base origin; encode components for their actual destination.</li><li><a href="./07-core-apis.html#t07-q09">Streams</a>: <strong>When <code>write()</code> returns <code>false</code>, the chunk was accepted: pause further writes until <code>drain</code> or failure.</strong> Await <code>pipeline()</code>; queue thresholds do not bound all memory.</li><li><a href="./07-core-apis.html#t07-q10">Lines and input</a>: <strong>A readline interface and its source stream have separate lifetimes.</strong> Observe source errors, close owned resources and impose input limits; readline does not cap line size.</li><li><a href="./07-core-apis.html#t07-q11">Cryptography</a>: <strong>Hash: change detection; HMAC/signature: authenticity; encryption: secrecy; password hashing: expensive salted verification.</strong> Choose the primitive for the goal and protect its keys.</li><li><a href="./07-core-apis.html#t07-q12">Compression</a>: <strong>Limit compressed input and expanded output separately.</strong> Backpressure does not cap total expansion, and compression provides neither secrecy nor authenticity.</li></ul><h2 id="framework-foundations" tabindex="-1">Framework foundations <a class="header-anchor" href="#framework-foundations" aria-label="Permalink to “Framework foundations”">​</a></h2><ul><li><a href="./16-frameworks.html#t16-q01">Framework responsibilities</a>: <strong>Node supplies the runtime; frameworks organize HTTP handling.</strong> MVC separates model, view and controller; an API commonly returns data instead of a rendered page.</li><li><a href="./16-frameworks.html#t16-q02">Framework choice</a>: <strong>Choose for application needs, team knowledge and measured constraints.</strong> Learn one stack well before comparing alternatives for a concrete reason.</li><li><a href="./16-frameworks.html#t16-q03">App versus server</a>: <strong>The app defines request behavior; the server owns the listening port and connections.</strong> Keep startup separate so importing the app does not open a port.</li><li><a href="./16-frameworks.html#t16-q04">Configuration and dependencies</a>: <strong>Validate settings before opening resources, then pass settings and services into the app.</strong> The code that acquires resources also owns failure cleanup and shutdown.</li></ul><h2 id="put-it-into-practice" tabindex="-1">Put it into practice <a class="header-anchor" href="#put-it-into-practice" aria-label="Permalink to “Put it into practice”">​</a></h2><p><a href="./progressive-projects.html#project-1-foundations-cli">Build a Foundations CLI</a>: keep terminal parsing in the entry point, business operations reusable and storage behind an explicit interface. Check results, failures and cleanup before extending the application.</p>',20)])])}const p=a(n,[["render",s]]);export{u as __pageData,p as default};
